import subprocess, tempfile, os, sys, json, uuid, glob, hashlib, time
REAL = os.getcwd()
S = os.path.join(tempfile.mkdtemp(), 'c.sqlite')
def c(*a):
    return subprocess.run([sys.executable, '_tools/coord.py', '--store', S, *a], capture_output=True, text=True)
def git(d, *a):
    return subprocess.run(['git', '-c', 'user.email=a@b.c', '-c', 'user.name=x', '-C', d, *a], capture_output=True, text=True)
def ws(branch, items=(), settings=None):
    d = os.path.realpath(tempfile.mkdtemp())
    git(d, 'init', '-q', '-b', branch)
    git(d, 'commit', '-q', '--allow-empty', '-m', 'x')
    os.makedirs(os.path.join(d, '_backlog'))
    for i, title, touches in items:
        json.dump({'id': i, 'title': title, 'touches': touches}, open(os.path.join(d, '_backlog', i + '.json'), 'w'))
    if settings:
        json.dump({'coordination': settings}, open(os.path.join(d, 'settings.json'), 'w'))
    return d
def label(sid):
    return 's-' + hashlib.sha256(sid.lower().encode()).hexdigest()[:6]
def hook(sid, op, event, cwd, store=None, **extra):
    payload = dict(hook_event_name=event, session_id=sid, cwd=cwd, **extra)
    t = time.time()
    r = subprocess.run([sys.executable, '.claude/hooks/coord_hook.py'], input=json.dumps(payload), capture_output=True, text=True,
                       env=dict(os.environ, KB_COORD_STORE=store or S, KB_OPERATOR=op), cwd=REAL)
    try:
        out = json.loads(r.stdout)
    except ValueError:
        out = {}
    return r.returncode, time.time() - t, out
def msg(out):
    return out.get('systemMessage', ''), out.get('hookSpecificOutput', {}).get('additionalContext', '')
def clean(*sids):
    for s in sids:
        for f in glob.glob(os.path.join(REAL, '_cache', 'coord_hook', s + '*')):
            os.remove(f)
def events(kind=None):
    rows = json.loads(c('wait', '--since', '0', '--timeout', '0').stdout)['events']
    return [e for e in rows if kind is None or e['kind'] == kind]
def bash(command):
    return dict(tool_name='Bash', tool_input={'command': command})
def edit(cwd, name, tool='Edit'):
    given = {'file_path': os.path.join(cwd, name)}
    given.update({'content': 'a'} if tool == 'Write' else {'old_string': 'a', 'new_string': 'b'})
    return dict(tool_name=tool, tool_input=given)
LAND = ('ST-ab12cd34', 'Lock the landing queue', ['_tools/bl_land.py', '_tools/coord.py'])
MINE = ('ST-ef56gh78', 'Show the queue in kbmon', ['_tools/bl_land.py'])
def other_working(sid='', op='op-aaaa', states=('claimed', 'working')):
    """The other session: its workspace on the branch of ST-ab12cd34, its SessionStart, and the run states of its item."""
    d = ws('work/ST-ab12cd34', [LAND])
    hook(sid, op, 'SessionStart', d, source='startup')
    for s in states:
        c('transition', 'run/ST-ab12cd34', '--to', s)
    return d

